PATTERN = re.compile(r'const ruMIG2CheckDetails = (.*);')

def patch(text):
    matches = list(PATTERN.finditer(text))
    if len(matches) != 1: raise ValueError('Expected exactly one overlay')
    m = matches[0]; raw = m.group(1)
    if hashlib.sha256(raw.encode()).hexdigest() != EXPECTED: raise ValueError('MIG12 overlay source witness changed')
    data = json.loads(raw)
    if len(data) != 128 or len(NOTES) != 18: raise ValueError('Unexpected catalog size')
    for key, value in NOTES.items():
        if 'filteringNote' in data[key] or not re.search(r'[А-Яа-яЁё]', value): raise ValueError(key)
        data[key]['filteringNote'] = value
    result = json.dumps(data, ensure_ascii=False, separators=(',', ':'))
    return text[:m.start(1)] + result + text[m.end(1):]

def main():
    p=argparse.ArgumentParser();p.add_argument('--candidate',type=Path,required=True);p.add_argument('--report',type=Path,required=True);a=p.parse_args()
    f=a.candidate/'src/modules/Reporting/templates/report-scripts.js'
    orig=a.candidate/'src/modules/Core/adPEAS-FindingDefinitions.ps1';sha=hashlib.sha256(orig.read_bytes()).hexdigest()
    s=f.read_text(encoding='utf-8-sig');f.write_text(patch(s),encoding='utf-8-sig')
    assert sha==hashlib.sha256(orig.read_bytes()).hexdigest()
    a.report.write_text(json.dumps(dict(Schema='adPEAS-RU.2.11.0.MIG13.1',CheckTypes=128,FilteringNotesTranslated=18,CanonicalFindingDefinitionsPreserved=True,OriginalDefinitionsSha256=sha,ProductionReady=False,RealADTestPerformed=False),indent=2)+'\n',encoding='utf-8-sig')
if __name__=='__main__': main()
